import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function Register() {
  const [nom, setNom] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("");
  const [classId, setClassId] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const navigate = useNavigate();

  const handleRegister = async (e) => {
    e.preventDefault();
    if (!nom || !email || !password || !role) {
      setError("Tous les champs sont requis");
      return;
    }

    try {
      const res = await fetch("http://localhost:5000/api/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ nom, email, password, role, class_id: classId || null }),
      });

      const data = await res.json();
      if (!res.ok) {
        setError(data.message);
        return;
      }

      setSuccess("Compte créé avec succès ! Vous pouvez vous connecter.");
      setError("");
      // reset form
      setNom(""); setEmail(""); setPassword(""); setRole(""); setClassId("");
      // redirect after 2s
      setTimeout(() => navigate("/"), 2000);
    } catch (err) {
      setError("Erreur serveur");
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      padding: "20px"
    }}>
      <div style={{
        background: "white",
        borderRadius: "12px",
        boxShadow: "0 10px 30px rgba(0, 0, 0, 0.2)",
        padding: "40px",
        width: "100%",
        maxWidth: "420px",
        textAlign: "center"
      }}>
        <h2 style={{ color: "#333", marginBottom: "10px", fontSize: "28px" }}>Inscription</h2>
        <p style={{ color: "#666", marginBottom: "30px" }}>Créer votre compte</p>

        <form onSubmit={handleRegister}>
          {error && <p style={{ color: "red" }}>{error}</p>}
          {success && <p style={{ color: "green" }}>{success}</p>}

          <input
            type="text" placeholder="Nom"
            value={nom} onChange={e => setNom(e.target.value)}
            style={{ width: "100%", padding: "12px", marginBottom: "15px", borderRadius: "8px", border: "1px solid #ddd" }}
          />

          <input
            type="email" placeholder="Email"
            value={email} onChange={e => setEmail(e.target.value)}
            style={{ width: "100%", padding: "12px", marginBottom: "15px", borderRadius: "8px", border: "1px solid #ddd" }}
          />

          <input
            type="password" placeholder="Mot de passe"
            value={password} onChange={e => setPassword(e.target.value)}
            style={{ width: "100%", padding: "12px", marginBottom: "15px", borderRadius: "8px", border: "1px solid #ddd" }}
          />

          <select value={role} onChange={e => setRole(e.target.value)} style={{ width: "100%", padding: "12px", marginBottom: "15px", borderRadius: "8px", border: "1px solid #ddd" }}>
            <option value="">-- Sélectionner rôle --</option>
            <option value="student">Étudiant</option>
            <option value="prof">Professeur</option>
          </select>

          {role === "student" && (
            <input
              type="number" placeholder="ID de la classe"
              value={classId} onChange={e => setClassId(e.target.value)}
              style={{ width: "100%", padding: "12px", marginBottom: "15px", borderRadius: "8px", border: "1px solid #ddd" }}
            />
          )}

          <button type="submit" style={{
            width: "100%", padding: "14px", backgroundColor: "#667eea", color: "white",
            border: "none", borderRadius: "8px", fontSize: "16px", fontWeight: "600", cursor: "pointer"
          }}>S'inscrire</button>
        </form>

        <p style={{ marginTop: "25px", color: "#666", fontSize: "15px" }}>
          Déjà un compte ? <a href="/" style={{ color: "#667eea" }}>Se connecter</a>
        </p>
      </div>
    </div>
  );
}

export default Register;
